/* Apple's chat: Messages' prompt bubble (18 px corners, accent-tinted, no edge), cards on the
   quaternary system fill with a separator hairline, secondary text as dark as secondaryLabel can be
   while it stays readable, and links in linkColor (systemBlue a step toward the label, which is
   what #0068DA light and #419CFF dark are).
   Only cmux.agentPane.style/1 tokens (schemas/agent-pane/style-tokens.json), on :root: paint, so
   nothing in the transcript moves when this applies or reloads. Every color is made from the
   theme's own (--agent-text, --agent-accent, --agent-page-bg), so it reads over Apple and Apple
   Dark and over any theme of your own. */
:root {
  --cv-user-bubble-tint: color-mix(in srgb, var(--agent-accent) 15%, transparent);
  --cv-user-bubble-edge: transparent;
  --cv-user-bubble-radius: 18px;
  --cv-card-fill: color-mix(in srgb, var(--agent-text) 5%, transparent);
  --cv-card-ring: color-mix(in srgb, var(--agent-text) 10%, transparent);
  --cv-text-muted: color-mix(in srgb, var(--agent-text) 74%, transparent);
  --cv-text-dim: color-mix(in srgb, var(--agent-text) 66%, transparent);
  --cv-link: color-mix(in srgb, var(--agent-accent) 76%, var(--agent-text));
  --agent-link: color-mix(in srgb, var(--agent-accent) 76%, var(--agent-text));

  /* Pending cmux#46490 (--cv-user-bubble-text): the true iMessage bubble, a solid systemBlue pill
     with white text, needs the bubble's own ink. Once that lands, the pair is:
       --cv-user-bubble-tint: var(--agent-accent);
       --cv-user-bubble-text: var(--agent-page-bg) in light, white in dark (needs light-dark()).
     Until then the tint stays light enough for the transcript's own text. */

  /* Pending cmux#46846 (--menu-*): macOS 26 menus and popovers. Inert until it lands.
     A vibrant panel (the page at 72% over the glass) with 10 px corners and a 5 px inset, 22 pt
     rows (NSMenu's), an inset 6 px accent capsule on the highlighted row, shortcuts in the
     secondary label at the right, bold gray section headers in the small system size, separators
     inset 10 px, destructive rows in the theme's red (systemRed, the default), and submenus that
     overlap their menu by the inset so their first row lines up with the row that opened them. */
  --menu-radius: 10px;
  --menu-padding: 5px;
  --menu-fill: color-mix(in srgb, var(--agent-page-bg) 72%, transparent);
  --menu-border: color-mix(in srgb, var(--agent-text) 12%, transparent);
  --menu-row-height: 22px;
  --menu-hover-fill: color-mix(in srgb, var(--agent-accent) 20%, transparent);
  --menu-hover-radius: 6px;
  --menu-separator: color-mix(in srgb, var(--agent-text) 12%, transparent);
  --menu-separator-inset: 10px;
  --menu-label-color: color-mix(in srgb, var(--agent-text) 72%, transparent);
  --menu-label-weight: 600;
  --menu-label-size: var(--text-caption);
  --menu-shortcut-color: color-mix(in srgb, var(--agent-text) 72%, transparent);
  --menu-subtitle-color: color-mix(in srgb, var(--agent-text) 72%, transparent);
  --menu-disabled-opacity: 0.35;
  --menu-submenu-offset: -5px;
  --menu-submenu-align-offset: -5px;
}

